class CommandLineMoreTest(unittest.TestCase):
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

    def run_cli(self, *args):
        return subprocess.run([sys.executable, "-m", "confkit", *args],
                              cwd=self.root, capture_output=True, text=True)

    def test_prints_whole_config_as_json(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "c.ini")
            with open(path, "w", encoding="utf-8") as handle:
                handle.write("[s]\nv = [1, 2]\n")
            result = self.run_cli(path)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, '{\n  "s": {\n    "v": [\n      1,\n      2\n    ]\n  }\n}\n')

    def test_missing_key_exits_2(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "c.ini")
            with open(path, "w", encoding="utf-8") as handle:
                handle.write("a = 1\n")
            result = self.run_cli(path, "--get", "a.b")
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stderr.strip(), "no such key: a.b")

    def test_parse_error_exits_1(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "c.ini")
            with open(path, "w", encoding="utf-8") as handle:
                handle.write("a = 1\na = 2\n")
            result = self.run_cli(path)
        self.assertEqual(result.returncode, 1)
        self.assertTrue(result.stderr.strip().endswith(":2: duplicate key 'a'"), result.stderr)


